/** Model repair output with explicit QA fixes. Render only in an opaque sandbox. */
export default "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>蓝色能源微电网调度实验室 | Blue Energy Microgrid Dispatch Laboratory</title>\n    <style>\n        * {\n            margin: 0;\n            padding: 0;\n            box-sizing: border-box;\n        }\n        \n        body {\n            font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"PingFang SC\", \"Hiragino Sans GB\", \"Microsoft YaHei\", sans-serif;\n            background: linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%);\n            padding: 20px;\n            color: #333;\n            line-height: 1.6;\n        }\n        \n        .container {\n            max-width: 1400px;\n            margin: 0 auto;\n            background: white;\n            border-radius: 12px;\n            box-shadow: 0 8px 32px rgba(0,0,0,0.1);\n            padding: 30px;\n        }\n        \n        .header {\n            text-align: center;\n            padding: 20px 0;\n            border-bottom: 3px solid #1565c0;\n            margin-bottom: 30px;\n        }\n        \n        .header h1 {\n            color: #1565c0;\n            font-size: 28px;\n            margin-bottom: 8px;\n        }\n        \n        .header h2 {\n            color: #666;\n            font-size: 18px;\n            font-weight: normal;\n            margin-bottom: 15px;\n        }\n        \n        .warning {\n            background: #fff3cd;\n            border: 2px solid #ffc107;\n            border-radius: 8px;\n            padding: 15px;\n            margin: 20px 0;\n            color: #856404;\n        }\n        \n        .control-panel {\n            background: #f5f9fc;\n            border: 2px solid #1565c0;\n            border-radius: 8px;\n            padding: 25px;\n            margin: 20px 0;\n        }\n        \n        .control-grid {\n            display: grid;\n            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));\n            gap: 20px;\n            margin: 20px 0;\n        }\n        \n        .control-item {\n            display: flex;\n            flex-direction: column;\n            gap: 8px;\n        }\n        \n        .control-item label {\n            font-weight: 600;\n            color: #1565c0;\n            font-size: 14px;\n        }\n        \n        .control-item input[type=\"range\"] {\n            width: 100%;\n            height: 6px;\n            border-radius: 3px;\n            background: #ddd;\n            outline: none;\n        }\n        \n        .control-item input[type=\"number\"] {\n            width: 100%;\n            padding: 8px;\n            border: 1px solid #ccc;\n            border-radius: 4px;\n            font-size: 14px;\n        }\n        \n        .control-item input[type=\"checkbox\"] {\n            width: 20px;\n            height: 20px;\n        }\n        \n        .strategy-selector {\n            margin: 20px 0;\n            display: flex;\n            gap: 20px;\n            flex-wrap: wrap;\n        }\n        \n        .strategy-selector label {\n            display: flex;\n            align-items: center;\n            gap: 8px;\n            cursor: pointer;\n            font-size: 15px;\n        }\n        \n        .button-group {\n            display: flex;\n            gap: 15px;\n            margin-top: 20px;\n        }\n        \n        .btn {\n            padding: 12px 30px;\n            border: none;\n            border-radius: 6px;\n            font-size: 16px;\n            cursor: pointer;\n            transition: all 0.3s;\n            font-weight: 600;\n        }\n        \n        .btn-primary {\n            background: #1565c0;\n            color: white;\n        }\n        \n        .btn-primary:hover {\n            background: #0d47a1;\n            transform: translateY(-2px);\n            box-shadow: 0 4px 12px rgba(21,101,192,0.4);\n        }\n        \n        .btn-secondary {\n            background: #757575;\n            color: white;\n        }\n        \n        .btn-secondary:hover {\n            background: #616161;\n        }\n        \n        .chart-container {\n            margin: 30px 0;\n            padding: 20px;\n            background: #fafafa;\n            border-radius: 8px;\n            border: 1px solid #e0e0e0;\n        }\n        \n        .chart-title {\n            font-size: 20px;\n            font-weight: 600;\n            color: #1565c0;\n            margin-bottom: 15px;\n        }\n        \n        canvas {\n            width: 100%;\n            height: 400px;\n            border-radius: 4px;\n            background: white;\n        }\n        \n        .table-container {\n            overflow-x: auto;\n            margin: 30px 0;\n            border-radius: 8px;\n            border: 1px solid #e0e0e0;\n        }\n        \n        table {\n            width: 100%;\n            border-collapse: collapse;\n            background: white;\n            font-size: 13px;\n        }\n        \n        th, td {\n            padding: 10px;\n            text-align: center;\n            border: 1px solid #e0e0e0;\n        }\n        \n        th {\n            background: #1565c0;\n            color: white;\n            font-weight: 600;\n            position: sticky;\n            top: 0;\n            z-index: 10;\n        }\n        \n        tr:nth-child(even) {\n            background: #f5f5f5;\n        }\n        \n        tr:hover {\n            background: #e3f2fd;\n            cursor: pointer;\n        }\n        \n        tr.selected {\n            background: #bbdefb !important;\n            font-weight: 600;\n        }\n        \n        .blackout-row {\n            background: #ffebee !important;\n        }\n        \n        .comparison-grid {\n            display: grid;\n            grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));\n            gap: 20px;\n            margin: 30px 0;\n        }\n        \n        .comparison-card {\n            border-radius: 8px;\n            padding: 20px;\n            box-shadow: 0 2px 8px rgba(0,0,0,0.1);\n        }\n        \n        .card-self {\n            background: #e3f2fd;\n            border-left: 4px solid #1565c0;\n        }\n        \n        .card-arbitrage {\n            background: #fff3e0;\n            border-left: 4px solid #e65100;\n        }\n        \n        .card-baseline {\n            background: #f5f5f5;\n            border-left: 4px solid #757575;\n        }\n        \n        .card-title {\n            font-size: 18px;\n            font-weight: 600;\n            margin-bottom: 15px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        \n        .metric-row {\n            display: flex;\n            justify-content: space-between;\n            padding: 8px 0;\n            border-bottom: 1px solid rgba(0,0,0,0.1);\n        }\n        \n        .metric-label {\n            color: #666;\n            font-size: 13px;\n        }\n        \n        .metric-value {\n            font-weight: 600;\n            font-size: 15px;\n        }\n        \n        .section {\n            margin: 40px 0;\n        }\n        \n        .section-title {\n            font-size: 22px;\n            font-weight: 600;\n            color: #1565c0;\n            margin-bottom: 20px;\n            padding-bottom: 10px;\n            border-bottom: 2px solid #e0e0e0;\n        }\n        \n        .info-box {\n            background: #e8f5e9;\n            border: 1px solid #4caf50;\n            border-radius: 4px;\n            padding: 15px;\n            margin: 20px 0;\n        }\n        \n        .info-box h3 {\n            color: #2e7d32;\n            margin-bottom: 10px;\n        }\n        \n        .info-box ul {\n            margin-left: 20px;\n        }\n        \n        .info-box li {\n            margin: 5px 0;\n            color: #1b5e20;\n        }\n        \n        .legend {\n            display: flex;\n            flex-wrap: wrap;\n            gap: 15px;\n            margin: 15px 0;\n            padding: 10px;\n            background: white;\n            border-radius: 4px;\n        }\n        \n        .legend-item {\n            display: flex;\n            align-items: center;\n            gap: 6px;\n            font-size: 13px;\n        }\n        \n        .legend-color {\n            width: 20px;\n            height: 3px;\n            border-radius: 2px;\n        }\n        \n        .value-display {\n            display: inline-block;\n            background: #e3f2fd;\n            padding: 2px 8px;\n            border-radius: 4px;\n            font-weight: 600;\n            margin-left: 10px;\n            color: #1565c0;\n        }\n        \n        @media (max-width: 768px) {\n            .container {\n                padding: 15px;\n            }\n            \n            .control-grid {\n                grid-template-columns: 1fr;\n            }\n            \n            .comparison-grid {\n                grid-template-columns: 1fr;\n            }\n            \n            .button-group {\n                flex-direction: column;\n            }\n            \n            canvas {\n                height: 300px;\n            }\n        }\n    </style>\n</head>\n<body>\n    <div class=\"container\">\n        <div class=\"header\">\n            <h1>🔋 蓝色能源微电网调度实验室</h1>\n            <h2>Blue Energy Microgrid Dispatch Laboratory</h2>\n            <div class=\"warning\">\n                ⚠️ <strong>小时步长合成数据 · 本地计算 · 无真实电网控制 · 仅供教学演示</strong><br>\n                ⚠️ <strong>Hourly synthetic data · Local computation · No real grid control · Educational demo only</strong>\n            </div>\n        </div>\n\n        <!-- 参数控制面板 -->\n        <div class=\"control-panel\">\n            <h3 class=\"section-title\">一、参数控制面板 · Parameter Control Panel</h3>\n            \n            <div class=\"control-grid\">\n                <div class=\"control-item\">\n                    <label for=\"loadScale\">负荷缩放系数 · Load Scale (0.5-2.0) <span class=\"value-display\" id=\"loadScaleVal\">1.0</span></label>\n                    <input type=\"range\" id=\"loadScale\" min=\"0.5\" max=\"2.0\" step=\"0.1\" value=\"1.0\">\n                </div>\n                \n                <div class=\"control-item\">\n                    <label for=\"pvPeak\">光伏峰值 · PV Peak (0-50 kW) <span class=\"value-display\" id=\"pvPeakVal\">30</span></label>\n                    <input type=\"range\" id=\"pvPeak\" min=\"0\" max=\"50\" step=\"1\" value=\"30\">\n                </div>\n                \n                <div class=\"control-item\">\n                    <label for=\"essCap\">储能容量 · ESS Capacity (30-200 kWh) <span class=\"value-display\" id=\"essCapVal\">90</span></label>\n                    <input type=\"range\" id=\"essCap\" min=\"30\" max=\"200\" step=\"10\" value=\"90\">\n                </div>\n                \n                <div class=\"control-item\">\n                    <label for=\"essPower\">储能功率 · ESS Power (10-50 kW) <span class=\"value-display\" id=\"essPowerVal\">24</span></label>\n                    <input type=\"range\" id=\"essPower\" min=\"10\" max=\"50\" step=\"2\" value=\"24\">\n                </div>\n                \n                <div class=\"control-item\">\n                    <label for=\"socInit\">初始SOC · Initial SOC (10-100%) <span class=\"value-display\" id=\"socInitVal\">50</span></label>\n                    <input type=\"range\" id=\"socInit\" min=\"10\" max=\"100\" step=\"5\" value=\"50\">\n                </div>\n                \n                <div class=\"control-item\">\n                    <label for=\"outageStart\">停电起始 · Outage Start (0-22h) <span class=\"value-display\" id=\"outageStartVal\">18</span></label>\n                    <input type=\"range\" id=\"outageStart\" min=\"0\" max=\"22\" step=\"1\" value=\"18\">\n                </div>\n                \n                <div class=\"control-item\">\n                    <label for=\"outageEnd\">停电结束 · Outage End (1-23h) <span class=\"value-display\" id=\"outageEndVal\">20</span></label>\n                    <input type=\"range\" id=\"outageEnd\" min=\"1\" max=\"23\" step=\"1\" value=\"20\">\n                </div>\n                \n                <div class=\"control-item\">\n                    <label style=\"display: flex; align-items: center; gap: 10px;\">\n                        <input type=\"checkbox\" id=\"enableBlackout\" checked>\n                        启用停电窗口 · Enable Outage Window\n                    </label>\n                </div>\n            </div>\n            \n            <div class=\"strategy-selector\">\n                <strong>调度策略选择 · Dispatch Strategy:</strong>\n                <label>\n                    <input type=\"radio\" name=\"strategy\" value=\"self_use\" checked>\n                    🔵 自用优先 (Self-Consumption)\n                </label>\n                <label>\n                    <input type=\"radio\" name=\"strategy\" value=\"price_arbitrage\">\n                    🟠 电价套利 (ToU Arbitrage)\n                </label>\n                <label>\n                    <input type=\"radio\" name=\"strategy\" value=\"comparison\">\n                    📊 双策略对照 (Both Comparison)\n                </label>\n            </div>\n            \n            <p id=\"scenarioError\" role=\"alert\" aria-live=\"polite\" style=\"color:#b71c1c;font-weight:600\"></p>\n            <div class=\"button-group\">\n                <button class=\"btn btn-primary\" onclick=\"runSimulation()\">▶ 运行计算 Run</button>\n                <button class=\"btn btn-secondary\" onclick=\"resetToDefault()\">↻ 重置样例 Reset</button>\n            </div>\n        </div>\n\n        <!-- 主曲线视图 -->\n        <div class=\"section\">\n            <h3 class=\"section-title\">二、主曲线视图 · Main Curve Visualization</h3>\n            <div class=\"chart-container\">\n                <div class=\"chart-title\">功率曲线（24小时） · Power Curves (24 Hours)</div>\n                <div class=\"legend\">\n                    <div class=\"legend-item\"><div class=\"legend-color\" style=\"background:#1a3a5c; height:4px;\"></div> 负荷 Load</div>\n                    <div class=\"legend-item\"><div class=\"legend-color\" style=\"background:#e8a020; height:4px;\"></div> 光伏 PV</div>\n                    <div class=\"legend-item\"><div class=\"legend-color\" style=\"background:#2e7d32; height:4px;\"></div> 购电 Grid Import</div>\n                    <div class=\"legend-item\"><div class=\"legend-color\" style=\"background:#1565c0; height:4px; border:2px dashed #1565c0;\"></div> 充电 Charge</div>\n                    <div class=\"legend-item\"><div class=\"legend-color\" style=\"background:#c62828; height:4px; border:2px dashed #c62828;\"></div> 放电 Discharge</div>\n                    <div class=\"legend-item\"><div class=\"legend-color\" style=\"background:#6a1b9a; height:4px;\"></div> SOC (右轴)</div>\n                    <div class=\"legend-item\"><div class=\"legend-color\" style=\"background:#ffebee; height:12px; width:30px;\"></div> 停电窗口 Outage</div>\n                </div>\n                <canvas id=\"powerChart\"></canvas>\n            </div>\n            \n            <div class=\"chart-container\">\n                <div class=\"chart-title\">SOC 轨迹曲线 · SOC Trajectory</div>\n                <canvas id=\"socChart\"></canvas>\n            </div>\n        </div>\n\n        <!-- 逐时账本表格 -->\n        <div class=\"section\">\n            <h3 class=\"section-title\">三、逐时账本表格 · Hourly Ledger Table</h3>\n            <div class=\"table-container\">\n                <table id=\"dataTable\">\n                    <thead>\n                        <tr>\n                            <th>时 h</th>\n                            <th>负荷 Load<br>(kW)</th>\n                            <th>光伏 PV<br>(kW)</th>\n                            <th>购电 Import<br>(kW)</th>\n                            <th>充电 Chr<br>(kW)</th>\n                            <th>放电 Dis<br>(kW)</th>\n                            <th>售电 Export<br>(kW)</th>\n                            <th>弃电 Curt<br>(kW)</th>\n                            <th>缺口 Shortage<br>(kW)</th>\n                            <th>SOC起<br>(%)</th>\n                            <th>SOC终<br>(%)</th>\n                            <th>电价 Pr<br>(¥/kWh)</th>\n                            <th>时费 Cost<br>(¥)</th>\n                            <th>备注 Note</th>\n                        </tr>\n                    </thead>\n                    <tbody id=\"dataTableBody\">\n                    </tbody>\n                </table>\n            </div>\n        </div>\n\n        <!-- 策略对照面板 -->\n        <div class=\"section\">\n            <h3 class=\"section-title\">四、策略对照面板 · Strategy Comparison Dashboard</h3>\n            <div class=\"comparison-grid\" id=\"comparisonGrid\">\n            </div>\n        </div>\n\n        <!-- 计算验证清单 -->\n        <div class=\"section\">\n            <h3 class=\"section-title\">五、计算验证清单 · Calculation Verification</h3>\n            <div class=\"info-box\">\n                <h3>✅ 动态不变量检查结果</h3>\n                <ul id=\"verificationList\">\n                    <li>等待首次计算... Waiting for first run...</li>\n                </ul>\n            </div>\n        </div>\n    </div>\n\n    <script>\n        /* \n         * ========== 修复说明 ==========\n         * \n         * 问题1修复：loadScale滑块即时更新\n         * - 所有input[type=\"range\"]的input事件现在立即调用updateValueDisplaysAndRecalc()\n         * - 更新显示标签后立即重新计算，无需点击Run按钮\n         * \n         * 问题2修复：无储能基线停电处理\n         * - noStorageBaseline()函数现在接收blackout参数\n         * - 停电时gridImport=0, loadServed=min(pv,load), gap=load-loadServed\n         * - 停电时无法出口的PV记为curtail\n         * \n         * 问题3修复：起止时段校验与停电开关\n         * - 添加enableBlackout复选框，允许禁用停电窗口\n         * - runSimulation()开始时校验outageStart<=outageEnd\n         * - 所有滑块关联label已通过id正确绑定\n         * \n         * 问题4修复：动态验证清单\n         * - 新增runVerification()函数，实际检查每小时的能量守恒、SOC边界等\n         * - 验证结果动态写入页面，不再是静态\"通过\"文案\n         * \n         * 其他修复：\n         * - 表格行点击改为仅更新视图，不重新计算（修复[高-04]）\n         * - 能量守恒计算修正：不照搬审查报告的错误建议\n         * - 停电时curtail逻辑：储能和无储能都正确处理无法出口的电量\n         */\n        \n        // ========== 核心计算模块 ==========\n        \n        // 固定种子数据\n        const SEED_LOAD = [6.0, 5.5, 5.2, 5.0, 5.0, 5.5, 8.0, 12.0, 15.0, 16.0, 14.0, 13.0,\n                           13.5, 14.0, 15.0, 17.0, 19.0, 22.0, 25.0, 24.0, 21.0, 16.0, 12.0, 8.0];\n        \n        const SEED_PV_PROFILE = [0, 0, 0, 0, 0, 0, 0.067, 0.267, 0.533, 0.733, 0.900, 1.000,\n                                 1.000, 0.933, 0.800, 0.600, 0.400, 0.200, 0.067, 0, 0, 0, 0, 0];\n        \n        const PRICE = [0.30, 0.30, 0.30, 0.30, 0.30, 0.30, 0.30, 0.50, 0.50, 0.50,\n                       0.80, 0.80, 0.80, 0.80, 0.80, 0.50, 0.50, 0.50, 0.80, 0.80,\n                       0.80, 0.50, 0.50, 0.30];\n        \n        const PRICE_SELL = 0.20;\n        const CARBON_FACTOR = 0.581;\n        \n        let currentParams = {\n            loadScale: 1.0,\n            pvPeak: 30,\n            essCap: 90,\n            essPower: 24,\n            socInit: 50,\n            outageStart: 18,\n            outageEnd: 20,\n            enableBlackout: true,\n            strategy: 'self_use'\n        };\n        \n        let currentResults = null;\n        let selectedHour = -1;\n        \n        // 辅助函数\n        function clamp(val, min, max) {\n            return Math.max(min, Math.min(max, val));\n        }\n        \n        function isBlackout(h, params) {\n            if (!params.enableBlackout) return false;\n            return h >= params.outageStart && h <= params.outageEnd;\n        }\n        \n        function updateSOC(socIn, charge, discharge, storage) {\n            const energyIn = charge * 0.95;\n            const energyOut = discharge / 0.95;\n            const deltaSOC = (energyIn - energyOut) / storage.essCap * 100;\n            return clamp(socIn + deltaSOC, 10, 100);\n        }\n        \n        // 自用优先策略\n        function selfUsePriority(load, pv, soc, storage, blackout) {\n            const pvToLoad = Math.min(pv, load);\n            let loadRemain = load - pvToLoad;\n            const pvSurplus = pv - pvToLoad;\n            \n            let charge = 0;\n            let pvToGrid = pvSurplus;\n            let curtail = 0;\n            \n            // PV剩余充电\n            if (pvSurplus > 0 && soc < 100) {\n                const maxChargePower = Math.min(\n                    pvSurplus,\n                    storage.essPower,\n                    (100 - soc) * storage.essCap / 100 / 0.95\n                );\n                charge = maxChargePower;\n                pvToGrid = pvSurplus - charge;\n            }\n            \n            // 停电时无法出口的PV记为弃电\n            if (blackout && pvToGrid > 0) {\n                curtail = pvToGrid;\n                pvToGrid = 0;\n            }\n            \n            // 储能放电\n            let discharge = 0;\n            if (loadRemain > 0 && soc > 10) {\n                const availableEnergy = (soc - 10) * storage.essCap / 100;\n                const maxDischargePower = Math.min(\n                    storage.essPower,\n                    availableEnergy * 0.95,\n                    loadRemain\n                );\n                discharge = maxDischargePower;\n                loadRemain -= discharge;\n            }\n            \n            // 购电\n            let gridImport = blackout ? 0 : loadRemain;\n            const loadServed = pvToLoad + discharge + gridImport;\n            const exportPower = pvToGrid;\n            const gap = Math.max(0, load - loadServed);\n            const socOut = updateSOC(soc, charge, discharge, storage);\n            \n            return { charge, discharge, gridImport, export: exportPower, curtail, loadServed, gap, socOut };\n        }\n        \n        // 电价套利策略\n        function priceArbitrage(h, price, load, pv, soc, storage, blackout) {\n            const isValley = (h >= 0 && h <= 6) || h === 23;\n            const isPeak = (h >= 10 && h <= 14) || (h >= 18 && h <= 20);\n            \n            const pvToLoad = Math.min(pv, load);\n            let loadRemain = load - pvToLoad;\n            const pvSurplus = pv - pvToLoad;\n            \n            let charge = 0;\n            let discharge = 0;\n            let gridImport = 0;\n            let gridCharge = 0;\n            let exportPower = 0;\n            let curtail = 0;\n            \n            if (isValley && soc < 90) {\n                const targetSOC = 90;\n                const maxChargeEnergy = (targetSOC - soc) * storage.essCap / 100 / 0.95;\n                const maxChargePower = Math.min(storage.essPower, maxChargeEnergy);\n                \n                const chargeFromPV = Math.min(pvSurplus, maxChargePower);\n                charge = chargeFromPV;\n                \n                if (charge < maxChargePower && !blackout) {\n                    const chargeFromGrid = Math.min(maxChargePower - charge, storage.essPower - charge);\n                    charge += chargeFromGrid;\n                    gridImport += chargeFromGrid;\n                    gridCharge += chargeFromGrid;\n                }\n                \n                const remainPV = pvSurplus - chargeFromPV;\n                if (blackout && remainPV > 0) {\n                    curtail = remainPV;\n                } else {\n                    exportPower = Math.max(remainPV, 0);\n                }\n                \n                gridImport += blackout ? 0 : loadRemain;\n            }\n            else if (isPeak && soc > 10) {\n                const availableEnergy = (soc - 10) * storage.essCap / 100;\n                const maxDischargePower = Math.min(storage.essPower, availableEnergy * 0.95);\n                \n                discharge = Math.min(maxDischargePower, loadRemain);\n                loadRemain -= discharge;\n                \n                gridImport = blackout ? 0 : loadRemain;\n                \n                if (blackout && pvSurplus > 0) {\n                    curtail = pvSurplus;\n                } else {\n                    exportPower = Math.max(pvSurplus, 0);\n                }\n            }\n            else {\n                if (pvSurplus > 0 && soc < 100) {\n                    const maxChargePower = Math.min(\n                        pvSurplus,\n                        storage.essPower,\n                        (100 - soc) * storage.essCap / 100 / 0.95\n                    );\n                    charge = maxChargePower;\n                    const remainPV = pvSurplus - charge;\n                    if (blackout && remainPV > 0) {\n                        curtail = remainPV;\n                    } else {\n                        exportPower = Math.max(remainPV, 0);\n                    }\n                } else {\n                    if (blackout && pvSurplus > 0) {\n                        curtail = pvSurplus;\n                    } else {\n                        exportPower = Math.max(pvSurplus, 0);\n                    }\n                }\n                \n                if (loadRemain > 0 && soc > 10) {\n                    const availableEnergy = (soc - 10) * storage.essCap / 100;\n                    const maxDischargePower = Math.min(\n                        storage.essPower,\n                        availableEnergy * 0.95,\n                        loadRemain\n                    );\n                    discharge = maxDischargePower;\n                    loadRemain -= discharge;\n                }\n                \n                gridImport = blackout ? 0 : loadRemain;\n            }\n            \n            const loadServed = pvToLoad + discharge + gridImport - gridCharge;\n            const gap = Math.max(0, load - loadServed);\n            const socOut = updateSOC(soc, charge, discharge, storage);\n            \n            return { charge, discharge, gridImport, export: exportPower, curtail, loadServed, gap, socOut };\n        }\n        \n        // 无储能基线\n        function noStorageBaseline(load, pv, blackout) {\n            const pvToLoad = Math.min(pv, load);\n            const loadRemain = load - pvToLoad;\n            \n            let gridImport = blackout ? 0 : loadRemain;\n            const loadServed = pvToLoad + gridImport;\n            const gap = Math.max(0, load - loadServed);\n            \n            const pvSurplus = pv - pvToLoad;\n            let exportPower = 0;\n            let curtail = 0;\n            \n            if (blackout && pvSurplus > 0) {\n                curtail = pvSurplus;\n            } else {\n                exportPower = Math.max(pvSurplus, 0);\n            }\n            \n            return {\n                charge: 0,\n                discharge: 0,\n                gridImport,\n                export: exportPower,\n                curtail,\n                loadServed,\n                gap,\n                socOut: 0\n            };\n        }\n        \n        // 运行全天模拟\n        function runDay(params, strategy) {\n            const hourly = [];\n            let soc = params.socInit;\n            \n            const load = SEED_LOAD.map(v => v * params.loadScale);\n            const pv = SEED_PV_PROFILE.map(v => v * params.pvPeak);\n            \n            for (let h = 0; h < 24; h++) {\n                const blackout = isBlackout(h, params);\n                let result;\n                \n                if (strategy === 'no_storage') {\n                    result = noStorageBaseline(load[h], pv[h], blackout);\n                } else if (strategy === 'self_use') {\n                    result = selfUsePriority(load[h], pv[h], soc, params, blackout);\n                } else {\n                    result = priceArbitrage(h, PRICE[h], load[h], pv[h], soc, params, blackout);\n                }\n                \n                const cost = result.gridImport * PRICE[h] - result.export * PRICE_SELL;\n                \n                hourly.push({\n                    t: h,\n                    load: load[h],\n                    pv: pv[h],\n                    gridImport: result.gridImport,\n                    charge: result.charge,\n                    discharge: result.discharge,\n                    loadServed: result.loadServed,\n                    export: result.export,\n                    curtail: result.curtail,\n                    gap: result.gap,\n                    socStart: soc,\n                    socEnd: result.socOut,\n                    price: PRICE[h],\n                    cost: cost,\n                    blackout: blackout\n                });\n                \n                soc = result.socOut;\n            }\n            \n            const netCost = hourly.reduce((sum, r) => sum + r.cost, 0);\n            const totalImport = hourly.reduce((sum, r) => sum + r.gridImport, 0);\n            const totalCarbon = totalImport * CARBON_FACTOR;\n            const peakImport = Math.max(...hourly.map(r => r.gridImport));\n            const totalCurtail = hourly.reduce((sum, r) => sum + r.curtail, 0);\n            const totalGap = hourly.reduce((sum, r) => sum + r.gap, 0);\n            \n            return {\n                hourly,\n                netCost,\n                totalImport,\n                totalCarbon,\n                peakImport,\n                totalCurtail,\n                totalGap\n            };\n        }\n        \n        // 动态验证函数\n        function runVerification(results) {\n            const checks = [];\n            const hourly = results.hourly;\n            \n            // 检查每小时能量守恒\n            let maxEnergyError = 0;\n            for (let i = 0; i < hourly.length; i++) {\n                const r = hourly[i];\n                const input = r.pv + r.gridImport + r.discharge;\n                const output = r.loadServed + r.charge + r.export + r.curtail;\n                const error = Math.abs(input - output);\n                maxEnergyError = Math.max(maxEnergyError, error);\n            }\n            \n            if (maxEnergyError < 1e-6) {\n                checks.push(`✅ 能量守恒：所有时段残差 < 1e-6 (实际最大 ${maxEnergyError.toExponential(2)})`);\n            } else {\n                checks.push(`❌ 能量守恒：发现残差 ${maxEnergyError.toFixed(6)} kW`);\n            }\n            \n            // 检查SOC边界\n            const socViolations = hourly.filter(r => r.socEnd < 9.99 || r.socEnd > 100.01);\n            if (socViolations.length === 0) {\n                checks.push(`✅ SOC边界：所有时段 SOC ∈ [10%, 100%]`);\n            } else {\n                checks.push(`❌ SOC边界：${socViolations.length} 个时段违反约束`);\n            }\n            \n            // 检查禁止同时充放电\n            const simultaneousCD = hourly.filter(r => r.charge > 0.01 && r.discharge > 0.01);\n            if (simultaneousCD.length === 0) {\n                checks.push(`✅ 禁止同时充放电：所有时段验证通过`);\n            } else {\n                checks.push(`❌ 同时充放电：${simultaneousCD.length} 个时段违反约束`);\n            }\n            \n            // 检查停电无进口\n            const blackoutImport = hourly.filter(r => r.blackout && r.gridImport > 0.01);\n            if (blackoutImport.length === 0) {\n                checks.push(`✅ 停电无进口：所有停电时段 gridImport = 0`);\n            } else {\n                checks.push(`❌ 停电进口：${blackoutImport.length} 个停电时段违反约束`);\n            }\n            \n            // 检查已供+缺口=负荷\n            let maxLoadError = 0;\n            for (let i = 0; i < hourly.length; i++) {\n                const r = hourly[i];\n                const error = Math.abs(r.loadServed + r.gap - r.load);\n                maxLoadError = Math.max(maxLoadError, error);\n            }\n            \n            if (maxLoadError < 1e-6) {\n                checks.push(`✅ 负荷守恒：loadServed + gap = load，最大残差 ${maxLoadError.toExponential(2)}`);\n            } else {\n                checks.push(`❌ 负荷守恒：发现残差 ${maxLoadError.toFixed(6)} kW`);\n            }\n            \n            // 检查功率上限\n            const powerViolations = hourly.filter(r => \n                r.charge > currentParams.essPower + 0.01 || \n                r.discharge > currentParams.essPower + 0.01\n            );\n            if (powerViolations.length === 0) {\n                checks.push(`✅ 功率约束：所有时段 charge/discharge ≤ ${currentParams.essPower} kW`);\n            } else {\n                checks.push(`❌ 功率约束：${powerViolations.length} 个时段超过限制`);\n            }\n            \n            // 检查非负性\n            const negativeViolations = hourly.filter(r =>\n                r.gridImport < -0.01 || r.charge < -0.01 || r.discharge < -0.01 ||\n                r.export < -0.01 || r.curtail < -0.01 || r.gap < -0.01\n            );\n            if (negativeViolations.length === 0) {\n                checks.push(`✅ 非负性：所有功率量 ≥ 0`);\n            } else {\n                checks.push(`❌ 非负性：${negativeViolations.length} 个时段出现负值`);\n            }\n            \n            // 统计信息\n            checks.push(`📊 总购电量：${results.totalImport.toFixed(1)} kWh`);\n            checks.push(`📊 总碳排放：${results.totalCarbon.toFixed(1)} kgCO₂`);\n            checks.push(`📊 峰值购电：${results.peakImport.toFixed(1)} kW`);\n            checks.push(`📊 总缺口：${results.totalGap.toFixed(1)} kWh`);\n            checks.push(`📊 总弃电：${results.totalCurtail.toFixed(1)} kWh`);\n            \n            return checks;\n        }\n        \n        // ========== UI 更新函数 ==========\n        \n        function updateValueDisplays() {\n            document.getElementById('loadScaleVal').textContent = currentParams.loadScale.toFixed(1);\n            document.getElementById('pvPeakVal').textContent = currentParams.pvPeak;\n            document.getElementById('essCapVal').textContent = currentParams.essCap;\n            document.getElementById('essPowerVal').textContent = currentParams.essPower;\n            document.getElementById('socInitVal').textContent = currentParams.socInit;\n            document.getElementById('outageStartVal').textContent = currentParams.outageStart;\n            document.getElementById('outageEndVal').textContent = currentParams.outageEnd;\n        }\n        \n        function updateValueDisplaysAndRecalc() {\n            runSimulation();\n        }\n        \n        function updateVerificationList(results) {\n            const list = document.getElementById('verificationList');\n            const checks = runVerification(results);\n            \n            list.innerHTML = checks.map(check => `<li>${check}</li>`).join('');\n        }\n        \n        function drawPowerChart(results) {\n            const canvas = document.getElementById('powerChart');\n            const ctx = canvas.getContext('2d');\n            const width = canvas.width = canvas.offsetWidth * 2;\n            const height = canvas.height = 800;\n            \n            ctx.clearRect(0, 0, width, height);\n            \n            const hourly = results.hourly;\n            const marginLeft = 80;\n            const marginRight = 80;\n            const marginTop = 40;\n            const marginBottom = 60;\n            const plotWidth = width - marginLeft - marginRight;\n            const plotHeight = height - marginTop - marginBottom;\n            \n            // 找最大值\n            const maxPower = Math.max(\n                ...hourly.map(r => Math.max(r.load, r.pv, r.gridImport, r.charge, r.discharge))\n            ) * 1.2;\n            \n            // 绘制停电区域\n            ctx.fillStyle = 'rgba(255, 235, 238, 0.5)';\n            for (let h = 0; h < 24; h++) {\n                if (hourly[h].blackout) {\n                    const x = marginLeft + (h / 23) * plotWidth;\n                    const x2 = marginLeft + ((h + 1) / 23) * plotWidth;\n                    ctx.fillRect(x, marginTop, x2 - x, plotHeight);\n                }\n            }\n            \n            // 绘制网格\n            ctx.strokeStyle = '#e0e0e0';\n            ctx.lineWidth = 1;\n            for (let i = 0; i <= 10; i++) {\n                const y = marginTop + (i / 10) * plotHeight;\n                ctx.beginPath();\n                ctx.moveTo(marginLeft, y);\n                ctx.lineTo(width - marginRight, y);\n                ctx.stroke();\n            }\n            \n            for (let i = 0; i <= 24; i++) {\n                const x = marginLeft + (i / 24) * plotWidth;\n                ctx.beginPath();\n                ctx.moveTo(x, marginTop);\n                ctx.lineTo(x, marginTop + plotHeight);\n                ctx.stroke();\n            }\n            \n            // 绘制坐标轴\n            ctx.strokeStyle = '#333';\n            ctx.lineWidth = 2;\n            ctx.beginPath();\n            ctx.moveTo(marginLeft, marginTop);\n            ctx.lineTo(marginLeft, marginTop + plotHeight);\n            ctx.lineTo(width - marginRight, marginTop + plotHeight);\n            ctx.stroke();\n            \n            // Y轴标签（左侧）\n            ctx.fillStyle = '#333';\n            ctx.font = '24px sans-serif';\n            ctx.textAlign = 'right';\n            for (let i = 0; i <= 10; i++) {\n                const y = marginTop + plotHeight - (i / 10) * plotHeight;\n                const val = (maxPower * i / 10).toFixed(1);\n                ctx.fillText(val, marginLeft - 10, y + 8);\n            }\n            \n            // Y轴标题\n            ctx.save();\n            ctx.translate(20, marginTop + plotHeight / 2);\n            ctx.rotate(-Math.PI / 2);\n            ctx.textAlign = 'center';\n            ctx.font = 'bold 28px sans-serif';\n            ctx.fillText('功率 Power (kW)', 0, 0);\n            ctx.restore();\n            \n            // X轴标签\n            ctx.textAlign = 'center';\n            ctx.font = '24px sans-serif';\n            for (let i = 0; i <= 24; i += 3) {\n                const x = marginLeft + (i / 24) * plotWidth;\n                ctx.fillText(i, x, marginTop + plotHeight + 40);\n            }\n            \n            ctx.font = 'bold 28px sans-serif';\n            ctx.fillText('时 Hour', marginLeft + plotWidth / 2, height - 10);\n            \n            // 右侧SOC轴\n            ctx.textAlign = 'left';\n            ctx.font = '24px sans-serif';\n            ctx.fillStyle = '#6a1b9a';\n            for (let i = 0; i <= 10; i++) {\n                const y = marginTop + plotHeight - (i / 10) * plotHeight;\n                const val = 10 + (90 * i / 10);\n                ctx.fillText(val.toFixed(0) + '%', width - marginRight + 10, y + 8);\n            }\n            \n            ctx.save();\n            ctx.translate(width - 20, marginTop + plotHeight / 2);\n            ctx.rotate(-Math.PI / 2);\n            ctx.textAlign = 'center';\n            ctx.font = 'bold 28px sans-serif';\n            ctx.fillText('SOC (%)', 0, 0);\n            ctx.restore();\n            \n            // 绘制曲线的函数\n            function drawLine(data, color, lineWidth, dash = []) {\n                ctx.strokeStyle = color;\n                ctx.lineWidth = lineWidth;\n                ctx.setLineDash(dash);\n                ctx.beginPath();\n                for (let i = 0; i < data.length; i++) {\n                    const x = marginLeft + (i / 23) * plotWidth;\n                    const y = marginTop + plotHeight - (data[i] / maxPower) * plotHeight;\n                    if (i === 0) ctx.moveTo(x, y);\n                    else ctx.lineTo(x, y);\n                }\n                ctx.stroke();\n                ctx.setLineDash([]);\n            }\n            \n            function drawSOCLine(data, color, lineWidth) {\n                ctx.strokeStyle = color;\n                ctx.lineWidth = lineWidth;\n                ctx.beginPath();\n                for (let i = 0; i < data.length; i++) {\n                    const x = marginLeft + (i / 23) * plotWidth;\n                    const y = marginTop + plotHeight - ((data[i] - 10) / 90) * plotHeight;\n                    if (i === 0) ctx.moveTo(x, y);\n                    else ctx.lineTo(x, y);\n                }\n                ctx.stroke();\n            }\n            \n            // 绘制各条曲线\n            drawLine(hourly.map(r => r.load), '#1a3a5c', 6);\n            drawLine(hourly.map(r => r.pv), '#e8a020', 6);\n            drawLine(hourly.map(r => r.gridImport), '#2e7d32', 5);\n            drawLine(hourly.map(r => r.charge), '#1565c0', 4, [10, 10]);\n            drawLine(hourly.map(r => r.discharge), '#c62828', 4, [10, 10]);\n            drawSOCLine(hourly.map(r => r.socEnd), '#6a1b9a', 5);\n            \n            // 绘制缺口柱状图\n            ctx.fillStyle = 'rgba(198, 40, 40, 0.6)';\n            for (let i = 0; i < hourly.length; i++) {\n                if (hourly[i].gap > 0) {\n                    const x = marginLeft + (i / 23) * plotWidth - 10;\n                    const barHeight = (hourly[i].gap / maxPower) * plotHeight;\n                    const y = marginTop + plotHeight - barHeight;\n                    ctx.fillRect(x, y, 20, barHeight);\n                }\n            }\n            \n            // 选中小时标记\n            if (selectedHour >= 0 && selectedHour < 24) {\n                const x = marginLeft + (selectedHour / 23) * plotWidth;\n                ctx.strokeStyle = '#f44336';\n                ctx.lineWidth = 3;\n                ctx.setLineDash([5, 5]);\n                ctx.beginPath();\n                ctx.moveTo(x, marginTop);\n                ctx.lineTo(x, marginTop + plotHeight);\n                ctx.stroke();\n                ctx.setLineDash([]);\n            }\n        }\n        \n        function drawSOCChart(results) {\n            const canvas = document.getElementById('socChart');\n            const ctx = canvas.getContext('2d');\n            const width = canvas.width = canvas.offsetWidth * 2;\n            const height = canvas.height = 800;\n            \n            ctx.clearRect(0, 0, width, height);\n            \n            const hourly = results.hourly;\n            const marginLeft = 80;\n            const marginRight = 60;\n            const marginTop = 40;\n            const marginBottom = 60;\n            const plotWidth = width - marginLeft - marginRight;\n            const plotHeight = height - marginTop - marginBottom;\n            \n            // 绘制网格\n            ctx.strokeStyle = '#e0e0e0';\n            ctx.lineWidth = 1;\n            for (let i = 0; i <= 10; i++) {\n                const y = marginTop + (i / 10) * plotHeight;\n                ctx.beginPath();\n                ctx.moveTo(marginLeft, y);\n                ctx.lineTo(width - marginRight, y);\n                ctx.stroke();\n            }\n            \n            for (let i = 0; i <= 24; i++) {\n                const x = marginLeft + (i / 24) * plotWidth;\n                ctx.beginPath();\n                ctx.moveTo(x, marginTop);\n                ctx.lineTo(x, marginTop + plotHeight);\n                ctx.stroke();\n            }\n            \n            // SOC下限标线\n            const minY = marginTop + plotHeight;\n            ctx.strokeStyle = '#ff5252';\n            ctx.lineWidth = 3;\n            ctx.setLineDash([15, 5]);\n            ctx.beginPath();\n            ctx.moveTo(marginLeft, minY);\n            ctx.lineTo(width - marginRight, minY);\n            ctx.stroke();\n            ctx.setLineDash([]);\n            \n            ctx.fillStyle = '#ff5252';\n            ctx.font = '24px sans-serif';\n            ctx.textAlign = 'left';\n            ctx.fillText('← 最低 SOC 10% (安全下限 Safety Limit)', width - marginRight - 500, minY - 10);\n            \n            // 坐标轴\n            ctx.strokeStyle = '#333';\n            ctx.lineWidth = 2;\n            ctx.beginPath();\n            ctx.moveTo(marginLeft, marginTop);\n            ctx.lineTo(marginLeft, marginTop + plotHeight);\n            ctx.lineTo(width - marginRight, marginTop + plotHeight);\n            ctx.stroke();\n            \n            // Y轴标签\n            ctx.fillStyle = '#333';\n            ctx.font = '24px sans-serif';\n            ctx.textAlign = 'right';\n            for (let i = 0; i <= 10; i++) {\n                const y = marginTop + plotHeight - (i / 10) * plotHeight;\n                const val = 10 + (90 * i / 10);\n                ctx.fillText(val.toFixed(0) + '%', marginLeft - 10, y + 8);\n            }\n            \n            // Y轴标题\n            ctx.save();\n            ctx.translate(20, marginTop + plotHeight / 2);\n            ctx.rotate(-Math.PI / 2);\n            ctx.textAlign = 'center';\n            ctx.font = 'bold 28px sans-serif';\n            ctx.fillText('SOC (%)', 0, 0);\n            ctx.restore();\n            \n            // X轴标签\n            ctx.textAlign = 'center';\n            ctx.font = '24px sans-serif';\n            for (let i = 0; i <= 24; i += 3) {\n                const x = marginLeft + (i / 24) * plotWidth;\n                ctx.fillText(i, x, marginTop + plotHeight + 40);\n            }\n            \n            ctx.font = 'bold 28px sans-serif';\n            ctx.fillText('时 Hour', marginLeft + plotWidth / 2, height - 10);\n            \n            // 绘制SOC曲线\n            ctx.strokeStyle = '#6a1b9a';\n            ctx.lineWidth = 6;\n            ctx.beginPath();\n            for (let i = 0; i < hourly.length; i++) {\n                const x = marginLeft + (i / 23) * plotWidth;\n                const y = marginTop + plotHeight - ((hourly[i].socEnd - 10) / 90) * plotHeight;\n                if (i === 0) ctx.moveTo(x, y);\n                else ctx.lineTo(x, y);\n            }\n            ctx.stroke();\n            \n            // 绘制关键点\n            ctx.fillStyle = '#6a1b9a';\n            for (let i = 0; i < hourly.length; i++) {\n                const x = marginLeft + (i / 23) * plotWidth;\n                const y = marginTop + plotHeight - ((hourly[i].socEnd - 10) / 90) * plotHeight;\n                ctx.beginPath();\n                ctx.arc(x, y, 8, 0, 2 * Math.PI);\n                ctx.fill();\n            }\n        }\n        \n        function updateTable(results) {\n            const tbody = document.getElementById('dataTableBody');\n            tbody.innerHTML = '';\n            \n            const hourly = results.hourly;\n            \n            for (let i = 0; i < hourly.length; i++) {\n                const r = hourly[i];\n                const tr = document.createElement('tr');\n                tr.className = r.blackout ? 'blackout-row' : '';\n                if (selectedHour === i) tr.classList.add('selected');\n                \n                const timeNote = r.t >= 0 && r.t <= 6 || r.t === 23 ? '谷 Valley' :\n                                 r.t >= 10 && r.t <= 14 || r.t >= 18 && r.t <= 20 ? '峰 Peak' : '平 Flat';\n                const outageNote = r.blackout ? ' 停电 Outage' : '';\n                \n                tr.innerHTML = `\n                    <td>${r.blackout ? '⚡' : ''} ${r.t}</td>\n                    <td>${r.load.toFixed(1)}</td>\n                    <td>${r.pv.toFixed(1)}</td>\n                    <td>${r.gridImport.toFixed(1)}</td>\n                    <td>${r.charge.toFixed(1)}</td>\n                    <td>${r.discharge.toFixed(1)}</td>\n                    <td>${r.export.toFixed(1)}</td>\n                    <td>${r.curtail.toFixed(1)}</td>\n                    <td style=\"color: ${r.gap > 0 ? '#c62828' : '#333'}; font-weight: ${r.gap > 0 ? 'bold' : 'normal'};\">${r.gap.toFixed(1)}</td>\n                    <td>${r.socStart.toFixed(1)}</td>\n                    <td>${r.socEnd.toFixed(1)}</td>\n                    <td>${r.price.toFixed(2)}</td>\n                    <td style=\"color: ${r.cost >= 0 ? '#c62828' : '#2e7d32'};\">${r.cost >= 0 ? '+' : ''}${r.cost.toFixed(2)}</td>\n                    <td>${timeNote}${outageNote}</td>\n                `;\n                \n                tr.onclick = () => {\n                    selectedHour = i;\n                    updateTable(currentResults);\n                    drawPowerChart(currentResults);\n                    drawSOCChart(currentResults);\n                };\n                \n                tbody.appendChild(tr);\n            }\n        }\n        \n        function updateComparison(results, strategy) {\n            const grid = document.getElementById('comparisonGrid');\n            \n            if (strategy === 'comparison') {\n                const selfResults = runDay(currentParams, 'self_use');\n                const arbResults = runDay(currentParams, 'price_arbitrage');\n                const baseResults = runDay(currentParams, 'no_storage');\n                \n                grid.innerHTML = `\n                    <div class=\"comparison-card card-self\">\n                        <div class=\"card-title\">🔵 自用优先 · Self-Consumption</div>\n                        <div class=\"metric-row\">\n                            <span class=\"metric-label\">净购电费用 · Net Cost</span>\n                            <span class=\"metric-value\">¥ ${selfResults.netCost.toFixed(2)}</span>\n                        </div>\n                        <div class=\"metric-row\">\n                            <span class=\"metric-label\">最高购电功率 · Peak Demand</span>\n                            <span class=\"metric-value\">${selfResults.peakImport.toFixed(1)} kW</span>\n                        </div>\n                        <div class=\"metric-row\">\n                            <span class=\"metric-label\">进口碳排 · Grid CO₂</span>\n                            <span class=\"metric-value\">${selfResults.totalCarbon.toFixed(1)} kg</span>\n                        </div>\n                        <div class=\"metric-row\">\n                            <span class=\"metric-label\">未供电量 · Shortage</span>\n                            <span class=\"metric-value\">${selfResults.totalGap.toFixed(1)} kWh</span>\n                        </div>\n                        <div class=\"metric-row\">\n                            <span class=\"metric-label\">弃电量 · Curtailment</span>\n                            <span class=\"metric-value\">${selfResults.totalCurtail.toFixed(1)} kWh</span>\n                        </div>\n                    </div>\n                    \n                    <div class=\"comparison-card card-arbitrage\">\n                        <div class=\"card-title\">🟠 电价套利 · ToU Arbitrage</div>\n                        <div class=\"metric-row\">\n                            <span class=\"metric-label\">净购电费用 · Net Cost</span>\n                            <span class=\"metric-value\">¥ ${arbResults.netCost.toFixed(2)}</span>\n                        </div>\n                        <div class=\"metric-row\">\n                            <span class=\"metric-label\">最高购电功率 · Peak Demand</span>\n                            <span class=\"metric-value\">${arbResults.peakImport.toFixed(1)} kW</span>\n                        </div>\n                        <div class=\"metric-row\">\n                            <span class=\"metric-label\">进口碳排 · Grid CO₂</span>\n                            <span class=\"metric-value\">${arbResults.totalCarbon.toFixed(1)} kg</span>\n                        </div>\n                        <div class=\"metric-row\">\n                            <span class=\"metric-label\">未供电量 · Shortage</span>\n                            <span class=\"metric-value\">${arbResults.totalGap.toFixed(1)} kWh</span>\n                        </div>\n                        <div class=\"metric-row\">\n                            <span class=\"metric-label\">弃电量 · Curtailment</span>\n                            <span class=\"metric-value\">${arbResults.totalCurtail.toFixed(1)} kWh</span>\n                        </div>\n                        <div style=\"margin-top: 15px; padding-top: 15px; border-top: 1px solid rgba(0,0,0,0.1); font-size: 14px;\">\n                            <strong>效果 Effect:</strong> 费用降低 ${((1 - arbResults.netCost / selfResults.netCost) * 100).toFixed(1)}%\n                        </div>\n                    </div>\n                    \n                    <div class=\"comparison-card card-baseline\">\n                        <div class=\"card-title\">⚪ 无储能基线 · No ESS Baseline</div>\n                        <div class=\"metric-row\">\n                            <span class=\"metric-label\">净购电费用 · Net Cost</span>\n                            <span class=\"metric-value\">¥ ${baseResults.netCost.toFixed(2)}</span>\n                        </div>\n                        <div class=\"metric-row\">\n                            <span class=\"metric-label\">最高购电功率 · Peak Demand</span>\n                            <span class=\"metric-value\">${baseResults.peakImport.toFixed(1)} kW</span>\n                        </div>\n                        <div class=\"metric-row\">\n                            <span class=\"metric-label\">进口碳排 · Grid CO₂</span>\n                            <span class=\"metric-value\">${baseResults.totalCarbon.toFixed(1)} kg</span>\n                        </div>\n                        <div class=\"metric-row\">\n                            <span class=\"metric-label\">未供电量 · Shortage</span>\n                            <span class=\"metric-value\">${baseResults.totalGap.toFixed(1)} kWh</span>\n                        </div>\n                        <div class=\"metric-row\">\n                            <span class=\"metric-label\">弃电量 · Curtailment</span>\n                            <span class=\"metric-value\">${baseResults.totalCurtail.toFixed(1)} kWh</span>\n                        </div>\n                        <div style=\"margin-top: 15px; padding-top: 15px; border-top: 1px solid rgba(0,0,0,0.1); font-size: 14px;\">\n                            <strong>对比 Comparison:</strong><br>\n                            自用策略节省费用 ${((1 - selfResults.netCost / baseResults.netCost) * 100).toFixed(1)}%<br>\n                            自用策略削减峰值 ${((1 - selfResults.peakImport / baseResults.peakImport) * 100).toFixed(1)}%\n                        </div>\n                    </div>\n                `;\n            } else {\n                grid.innerHTML = `\n                    <div class=\"comparison-card ${strategy === 'self_use' ? 'card-self' : 'card-arbitrage'}\">\n                        <div class=\"card-title\">${strategy === 'self_use' ? '🔵 自用优先 · Self-Consumption' : '🟠 电价套利 · ToU Arbitrage'}</div>\n                        <div class=\"metric-row\">\n                            <span class=\"metric-label\">净购电费用 · Net Cost</span>\n                            <span class=\"metric-value\">¥ ${results.netCost.toFixed(2)}</span>\n                        </div>\n                        <div class=\"metric-row\">\n                            <span class=\"metric-label\">最高购电功率 · Peak Demand</span>\n                            <span class=\"metric-value\">${results.peakImport.toFixed(1)} kW</span>\n                        </div>\n                        <div class=\"metric-row\">\n                            <span class=\"metric-label\">进口碳排 · Grid CO₂</span>\n                            <span class=\"metric-value\">${results.totalCarbon.toFixed(1)} kg</span>\n                        </div>\n                        <div class=\"metric-row\">\n                            <span class=\"metric-label\">未供电量 · Shortage</span>\n                            <span class=\"metric-value\">${results.totalGap.toFixed(1)} kWh</span>\n                        </div>\n                        <div class=\"metric-row\">\n                            <span class=\"metric-label\">弃电量 · Curtailment</span>\n                            <span class=\"metric-value\">${results.totalCurtail.toFixed(1)} kWh</span>\n                        </div>\n                    </div>\n                `;\n            }\n        }\n        \n        // ========== 主控制函数 ==========\n        \n        function runSimulation() {\n            // 读取参数\n            currentParams.loadScale = parseFloat(document.getElementById('loadScale').value);\n            currentParams.pvPeak = parseFloat(document.getElementById('pvPeak').value);\n            currentParams.essCap = parseFloat(document.getElementById('essCap').value);\n            currentParams.essPower = parseFloat(document.getElementById('essPower').value);\n            currentParams.socInit = parseFloat(document.getElementById('socInit').value);\n            currentParams.outageStart = parseInt(document.getElementById('outageStart').value);\n            currentParams.outageEnd = parseInt(document.getElementById('outageEnd').value);\n            currentParams.enableBlackout = document.getElementById('enableBlackout').checked;\n            currentParams.strategy = document.querySelector('input[name=\"strategy\"]:checked').value;\n            \n            // 校验停电时段\n            if (currentParams.enableBlackout && currentParams.outageStart > currentParams.outageEnd) {\n                document.getElementById('scenarioError').textContent = '错误：停电起始时间不能晚于结束时间 · Error: Outage start must ≤ end. 上方输入尚未应用；下方保留上次有效计算。 Inputs not applied; last valid results remain below.';\n                return;\n            }\n            \n            document.getElementById('scenarioError').textContent = '';\n            updateValueDisplays();\n            \n            // 运行计算\n            const strategy = currentParams.strategy === 'comparison' ? 'self_use' : currentParams.strategy;\n            currentResults = runDay(currentParams, strategy);\n            \n            // 更新视图\n            drawPowerChart(currentResults);\n            drawSOCChart(currentResults);\n            updateTable(currentResults);\n            updateComparison(currentResults, currentParams.strategy);\n            updateVerificationList(currentResults);\n        }\n        \n        function resetToDefault() {\n            document.getElementById('loadScale').value = 1.0;\n            document.getElementById('pvPeak').value = 30;\n            document.getElementById('essCap').value = 90;\n            document.getElementById('essPower').value = 24;\n            document.getElementById('socInit').value = 50;\n            document.getElementById('outageStart').value = 18;\n            document.getElementById('outageEnd').value = 20;\n            document.getElementById('enableBlackout').checked = true;\n            document.querySelector('input[name=\"strategy\"][value=\"self_use\"]').checked = true;\n            selectedHour = -1;\n            \n            runSimulation();\n        }\n        \n        // ========== 事件监听 ==========\n        \n        document.querySelectorAll('input[type=\"range\"]').forEach(input => {\n            input.addEventListener('input', updateValueDisplaysAndRecalc);\n        });\n        \n        document.getElementById('enableBlackout').addEventListener('change', runSimulation);\n        \n        document.querySelectorAll('input[name=\"strategy\"]').forEach(radio => {\n            radio.addEventListener('change', runSimulation);\n        });\n        \n        // 初始化\n        window.addEventListener('load', () => {\n            resetToDefault();\n        });\n        \n        // 响应式调整\n        window.addEventListener('resize', () => {\n            if (currentResults) {\n                drawPowerChart(currentResults);\n                drawSOCChart(currentResults);\n            }\n        });\n    </script>\n</body>\n</html>";
